  const groups={};(data||[]).forEach(r=>{const k=r.equipment_id;groups[k]??={...r,total:0,available:0};groups[k].total++;if(r.availability_status==='Available')groups[k].available++});
  const cats=[...new Set((data||[]).map(r=>r.category_name).filter(Boolean))].sort();
  const statuses=['Available','Borrowed','Reserved','Maintenance','Retired'];
  $('#content').innerHTML=`<div class="toolbar"><input id="eqSearch" class="search" placeholder="Search equipment, category, asset tag, serial number..."><select id="eqCategory" aria-label="Filter category"><option value="">All categories</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="eqStatus" aria-label="Filter availability"><option value="">All statuses</option>${statuses.map(c=>`<option>${c}</option>`).join('')}</select><button class="btn primary" ${isStaff()?'':'style="display:none"'} onclick="equipmentForm()">+ Add Equipment</button></div><div class="cards inventory-summary"><div class="card stat"><div class="label">Total units</div><div class="num">${(data||[]).length}</div></div><div class="card stat"><div class="label">Available</div><div class="num">${(data||[]).filter(x=>x.availability_status==='Available').length}</div></div><div class="card stat"><div class="label">Borrowed / reserved</div><div class="num">${(data||[]).filter(x=>['Borrowed','Reserved'].includes(x.availability_status)).length}</div></div><div class="card stat"><div class="label">Damaged / repair</div><div class="num">${(data||[]).filter(x=>['Damaged','For Repair'].includes(x.condition_status)||x.availability_status==='Maintenance').length}</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Equipment ID</th><th>Equipment</th><th>Category</th><th>Quantity</th><th>Available</th><th>Stock Alert</th><th>Condition</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody id="eqBody">${Object.values(groups).map(r=>`<tr data-search="${esc((r.equipment_id+' '+r.equipment_name+' '+(r.brand||'')+' '+(r.model||'')+' '+r.category_name+' '+(r.location||'')+' '+(r.asset_tag||'')+' '+(r.serial_number||'')).toLowerCase())}" data-category="${esc(r.category_name||'')}" data-status="${esc(r.availability_status||'')}"><td><b>EQ-${String(r.equipment_id).padStart(4,'0')}</b></td><td>${esc(r.equipment_name)}<br><small>${esc(r.brand||'')} ${esc(r.model||'')}</small></td><td>${esc(r.category_name)}</td><td>${r.total}</td><td>${r.available}</td><td>${isStaff()&&r.available<=1?`<span class="badge warn">Low stock</span>`:`<span class="muted">—</span>`}</td><td>${badge(r.condition_status)}</td><td>${esc(r.location||'')}</td><td>${badge(r.availability_status)}</td><td>${isAdmin()?`<button class="btn small" onclick="addEquipmentQuantity(${r.equipment_id})">+ Add Qty</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="10" class="empty">No equipment found.</td></tr>'}</tbody></table></div>`;
  const filterInventory=()=>$$('#eqBody tr').forEach(r=>{const term=$('#eqSearch').value.toLowerCase(),cat=$('#eqCategory').value,status=$('#eqStatus').value;r.style.display=r.dataset.search.includes(term)&&(!cat||r.dataset.category===cat)&&(!status||r.dataset.status===status)?'':'none'});
  $('#eqSearch').oninput=filterInventory;$('#eqCategory').onchange=filterInventory;$('#eqStatus').onchange=filterInventory;
